UPDATE `garbas` SET `title` = '{\"gu\":\"વરસે ભલે વાદળીને વાયુ ભલે વાય (રાંદલમાનો દીવડો)\",\"hi\":\"वरसे भले वादळीने वायु भले वाय (रांदलमानो दीवडो)\",\"en\":\"Varse Bhale Vadali Ne Vayu Bhale Vay (Randal Mano Divdo)\"}', `lyrics` = '{\"gu\":[\"વરસે ભલે વાદળીને વાયુ ભલે વાય,\",\"રાંદલમાનો દીવડો તોયે ન બુજાય તોયે ન બુજાય.\",\"કહી દો સુરજને કે ઉગે નહીં ઠાલો,\",\"મારી રાંદલમાનો દીવડો અજવાળાં પાથરે રે લોલ.\"],\"hi\":[\"वरसे भले वादळीने वायु भले वाय,\",\"रांदलमानो दीवडो तोये न बुजाय तोये न बुजाय.\",\"कही दो सुरजने के उगे नहीं ठाळो,\",\"मारी रांदलमानो दीवडो अजवाळां पाथरे रे लोल.\"],\"en\":[\"Varse bhale vaadaline vaayu bhale vaay,\",\"Randal maano deevado toye na bujaay toye na bujaay.\",\"Kahi do surajne ke uge nahi thaalo,\",\"Maari Randal maano deevado ajvaala paathare re lol.\"],\"sections\":[{\"type\":\"chorus\",\"label\":{\"gu\":\"મુખડું (પલ્લવ)\",\"hi\":\"मुखड़ा (पल्लव)\",\"en\":\"REFRAIN\"},\"lines\":{\"gu\":[\"વરસે ભલે વાદળીને વાયુ ભલે વાય,\",\"રાંદલમાનો દીવડો તોયે ન બુજાય તોયે ન બુજાય.\"],\"hi\":[\"वरसे भले वादळीने वायु भले वाय,\",\"रांदलमानो दीवडो तोये न बुजाय तोये न बुजाय.\"],\"en\":[\"Varse bhale vaadaline vaayu bhale vaay,\",\"Randal maano deevado toye na bujaay toye na bujaay.\"]}},{\"type\":\"verse\",\"label\":{\"gu\":\"ચરણ ૧\",\"hi\":\"चरण १\",\"en\":\"VERSE 1\"},\"lines\":{\"gu\":[\"કહી દો સુરજને કે ઉગે નહીં ઠાલો,\",\"મારી રાંદલમાનો દીવડો અજવાળાં પાથરે રે લોલ.\"],\"hi\":[\"कही दो सुरजने के उगे नहीं ठाळो,\",\"मारी रांदलमानो दीवडो अजवाळां पाथरे रे लोल.\"],\"en\":[\"Kahi do surajne ke uge nahi thaalo,\",\"Maari Randal maano deevado ajvaala paathare re lol.\"]}}]}', `search_text` = 'varse bhale vadali ne vayu bhale vay (randal mano divdo) \n વરસે ભલે વાદળીને વાયુ ભલે વાય (રાંદલમાનો દીવડો) \n वरसे भले वादळीने वायु भले वाय (रांदलमानो दीवडो) \n old and new evergreen garbas \n navratri garba \n old and new evergreen garbas \n varse bhale vaadaline vaayu bhale vaay, \n randal maano deevado toye na bujaay toye na bujaay. \n kahi do surajne ke uge nahi thaalo, \n maari randal maano deevado ajvaala paathare re lol. \n વરસે ભલે વાદળીને વાયુ ભલે વાય, \n રાંદલમાનો દીવડો તોયે ન બુજાય તોયે ન બુજાય. \n કહી દો સુરજને કે ઉગે નહીં ઠાલો, \n મારી રાંદલમાનો દીવડો અજવાળાં પાથરે રે લોલ. \n वरसे भले वादळीने वायु भले वाय, \n रांदलमानो दीवडो तोये न बुजाय तोये न बुजाय. \n कही दो सुरजने के उगे नहीं ठाळो, \n मारी रांदलमानो दीवडो अजवाळां पाथरे रे लोल.' WHERE `id` = 'randal-ma-no-divdo-toye-na-bujay-7c9f8d16';

UPDATE `garbas` SET `title` = '{\"gu\":\"જ્યારે રાત બધી રઢિયાળી થાય\",\"hi\":\"ज्यारे रात बधी रढियाळी थाय\",\"en\":\"Jyare Raat Badhi Radhiyali Thay\"}', `lyrics` = '{\"gu\":[\"જ્યારે રાત બધી રઢિયાળી થાય,\",\"જ્યારે દિવડાઓ જગ મગ થાય...\",\"મારી માવલડી રમવાને આવે,\",\"ચોકે ચોકે ગરબો ઘુમાવે...\"],\"hi\":[\"ज्यारे रात बधी रढियाळी थाय,\",\"ज्यारे दिवडाओ जग मग थाय...\",\"मारी मावलडी रमवाने आवे,\",\"चोके चोके गरबो घुमावे...\"],\"en\":[\"Jyare raat badhi radhiyaali thaay,\",\"Jyare divadaao jag mag thaay...\",\"Maari maavaladi ramvaane aave,\",\"Choke choke garbo ghumaave...\"],\"sections\":[{\"type\":\"chorus\",\"label\":{\"gu\":\"મુખડું\",\"hi\":\"मुखड़ा\",\"en\":\"CHORUS\"},\"lines\":{\"gu\":[\"જ્યારે રાત બધી રઢિયાળી થાય,\",\"જ્યારે દિવડાઓ જગ મગ થાય...\"],\"hi\":[\"ज्यारे रात बधी रढियाळी थाय,\",\"ज्यारे दिवडाओ जग मग थाय...\"],\"en\":[\"Jyare raat badhi radhiyaali thaay,\",\"Jyare divadaao jag mag thaay...\"]}},{\"type\":\"verse\",\"label\":{\"gu\":\"ચરણ\",\"hi\":\"चरण\",\"en\":\"VERSE\"},\"lines\":{\"gu\":[\"મારી માવલડી રમવાને આવે,\",\"ચોકે ચોકે ગરબો ઘુમાવે...\"],\"hi\":[\"मारी मावलडी रमवाने आवे,\",\"चोके चोके गरबो घुमावे...\"],\"en\":[\"Maari maavaladi ramvaane aave,\",\"Choke choke garbo ghumaave...\"]}}]}', `search_text` = 'jyare raat badhi radhiyali thay \n જ્યારે રાત બધી રઢિયાળી થાય \n ज्यारे रात बधी रढियाळी थाय \n old and new evergreen garbas \n navratri garba \n old and new evergreen garbas \n jyare raat badhi radhiyaali thaay, \n jyare divadaao jag mag thaay... \n maari maavaladi ramvaane aave, \n choke choke garbo ghumaave... \n જ્યારે રાત બધી રઢિયાળી થાય, \n જ્યારે દિવડાઓ જગ મગ થાય... \n મારી માવલડી રમવાને આવે, \n ચોકે ચોકે ગરબો ઘુમાવે... \n ज्यारे रात बधी रढियाळी थाय, \n ज्यारे दिवडाओ जग मग थाय... \n मारी मावलडी रमवाने आवे, \n चोके चोके गरबो घुमावे...' WHERE `id` = 'jyare-rat-badhi-radhiyali-thay-jyare-divdao-jagmag-thay-230becff';

UPDATE `garbas` SET `title` = '{\"en\":\"Gagan mandal ni gagardi gun garbi re\",\"gu\":\"ગગન મંડળની ગાગરડી, ગુણ ગરબી રે\",\"hi\":\"गगन मंडळनी गागरडी, गुण गरबी रे\"}', `lyrics` = '{\"gu\":[\"ગગન મંડળની ગાગરડી, ગુણ ગરબી રે,\",\"તેણે રમી ભવાની રાસ, ગાઉં ગુણ ગરબી રે.\",\"સુર-નર મુનિવર જોતાં રહ્યા, ગુણ ગરબી રે,\",\"અંબા રમે ચોકમાં રાસ, ગાઉં ગુણ ગરબી રે.\",\"અખંડ દીવડા ઝગમગે, ગુણ ગરબી રે,\",\"માના મંડપમાં અજવાશ, ગાઉં ગુણ ગરબી રે.\"],\"hi\":[\"गगन मंडळनी गागरडी, गुण गरबी रे,\",\"तेणे रमी भवानी रास, गाउं गुण गरबी रे.\",\"सुर-नर मुनिवर जोतां रह्या, गुण गरबी रे,\",\"अंबा रमे चोकमां रास, गाउं गुण गरबी रे.\",\"अखंड दीवडा झगमगे, गुण गरबी रे,\",\"माना मंडपमां अजवाश, गाउं गुण गरबी रे.\"],\"en\":[\"Gagan mandal ni gagardi, gun garbi re,\",\"Tene rami Bhavani raas, gaau gun garbi re.\",\"Sur-nar munivar jota rahya, gun garbi re,\",\"Amba rame chowk ma raas, gaau gun garbi re.\",\"Akhand deevada jagmage, gun garbi re,\",\"Maa na mandap ma ajvaash, gaau gun garbi re.\"],\"sections\":[{\"type\":\"chorus\",\"label\":{\"gu\":\"ગરબી પલ્લવ\",\"hi\":\"गरबी पल्लव\",\"en\":\"REFRAIN\"},\"lines\":{\"gu\":[\"ગગન મંડળની ગાગરડી, ગુણ ગરબી રે,\",\"તેણે રમી ભવાની રાસ, ગાઉં ગુણ ગરબી રે.\"],\"hi\":[\"गगन मंडळनी गागरडी, गुण गरबी रे,\",\"तेणे रमी भवानी रास, गाउं गुण गरबी रे.\"],\"en\":[\"Gagan mandal ni gagardi, gun garbi re,\",\"Tene rami Bhavani raas, gaau gun garbi re.\"]}},{\"type\":\"verse\",\"label\":{\"gu\":\"ચરણ ૧\",\"hi\":\"चरण १\",\"en\":\"VERSE 1\"},\"lines\":{\"gu\":[\"સુર-નર મુનિવર જોતાં રહ્યા, ગુણ ગરબી રે,\",\"અંબા રમે ચોકમાં રાસ, ગાઉં ગુણ ગરબી રે.\"],\"hi\":[\"सुर-नर मुनिवर जोतां रह्या, गुण गरबी रे,\",\"अंबा रमे चोकमां रास, गाउं गुण गरबी रे.\"],\"en\":[\"Sur-nar munivar jota rahya, gun garbi re,\",\"Amba rame chowk ma raas, gaau gun garbi re.\"]}},{\"type\":\"verse\",\"label\":{\"gu\":\"ચરણ ૨\",\"hi\":\"चरण २\",\"en\":\"VERSE 2\"},\"lines\":{\"gu\":[\"અખંડ દીવડા ઝગમગે, ગુણ ગરબી રે,\",\"માના મંડપમાં અજવાશ, ગાઉં ગુણ ગરબી રે.\"],\"hi\":[\"अखंड दीवडा झगमगे, गुण गरबी रे,\",\"माना मंडपमां अजवाश, गाउं गुण गरबी रे.\"],\"en\":[\"Akhand deevada jagmage, gun garbi re,\",\"Maa na mandap ma ajvaash, gaau gun garbi re.\"]}}]}', `search_text` = 'gagan mandal ni gagardi gun garbi re \n ગગન મંડળની ગાગરડી, ગુણ ગરબી રે \n गगन मंडळनी गागरडी, गुण गरबी रे \n old and new evergreen garbas \n navratri garba \n old and new evergreen garbas \n gagan mandal ni gagardi, gun garbi re, \n tene rami bhavani raas, gaau gun garbi re. \n sur-nar munivar jota rahya, gun garbi re, \n amba rame chowk ma raas, gaau gun garbi re. \n ગગન મંડળની ગાગરડી, ગુણ ગરબી રે, \n તેણે રમી ભવાની રાસ, ગાઉં ગુણ ગરબી રે. \n સુર-નર મુનિવર જોતાં રહ્યા, ગુણ ગરબી રે, \n અંબા રમે ચોકમાં રાસ, ગાઉં ગુણ ગરબી રે. \n गगन मंडळनी गागरडी, गुण गरबी रे, \n तेणे रमी भवानी रास, गाउं गुण गरबी रे. \n सुर-नर मुनिवर जोतां रह्या, गुण गरबी रे, \n अंबा रमे चोकमां रास, गाउं गुण गरबी रे.' WHERE `id` = 'gagan-mandal-ni-gagardi-gun-garbi-re-03f0d3bc';

UPDATE `garbas` SET `title` = '{\"en\":\"Sakhi marwad javu mari bhari juvani jay\",\"gu\":\"સખી મારવાડ ઝાવું રે... મારી ભરી ઝુવાની ઝાય\",\"hi\":\"सखी मारवाड झावुं रे... मारी भरी झुवानी झाय\"}', `lyrics` = '{\"gu\":[\"સખી મારવાડ જાવું રે, મારી ભરી જુવાની જાય,\",\"સખી મારવાડાના લાડકા, મને ભાળીને સીટી મારે...\",\"હું તો પાણીડાં ભરવાને ગઈ’તી રે સૈયર,\",\"મારી હેલ છલકાઈ જાય, મારી ચૂંદલડી લહેરાય...\"],\"hi\":[\"सखी मारवाड जावुं रे, मारी भरी जुवानी जाय,\",\"सखी मारवाडाना लाडका, मने भाळीने सीटी मारे...\",\"हूं तो पाणीडां भरवाने गई’ती रे सैयर,\",\"मारी हेल छलकाई जाय, मारी चूंदलडी लहेराय...\"],\"en\":[\"Sakhi Marwad jaavu re, maari bhari juvaani jaay,\",\"Sakhi Marwada na laadka, mane bhaaline seeti maare...\",\"Hoo to paanida bharvaane gai ti re saiyar,\",\"Maari hel chhalkaai jaay, maari chundaldi laheraay...\"],\"sections\":[{\"type\":\"chorus\",\"label\":{\"gu\":\"મુખડું\",\"hi\":\"मुखड़ा\",\"en\":\"CHORUS\"},\"lines\":{\"gu\":[\"સખી મારવાડ જાવું રે, મારી ભરી જુવાની જાય,\",\"સખી મારવાડાના લાડકા, મને ભાળીને સીટી મારે...\"],\"hi\":[\"सखी मारवाड जावुं रे, मारी भरी जुवानी जाय,\",\"सखी मारवाडाना लाडका, मने भाळीने सीटी मारे...\"],\"en\":[\"Sakhi Marwad jaavu re, maari bhari juvaani jaay,\",\"Sakhi Marwada na laadka, mane bhaaline seeti maare...\"]}},{\"type\":\"verse\",\"label\":{\"gu\":\"ચરણ\",\"hi\":\"चरण\",\"en\":\"VERSE\"},\"lines\":{\"gu\":[\"હું તો પાણીડાં ભરવાને ગઈ’તી રે સૈયર,\",\"મારી હેલ છલકાઈ જાય, મારી ચૂંદલડી લહેરાય...\"],\"hi\":[\"हूं तो पाणीडां भरवाने गई’ती रे सैयर,\",\"मारी हेल छलकाई जाय, मारी चूंदलडी लहेराय...\"],\"en\":[\"Hoo to paanida bharvaane gai ti re saiyar,\",\"Maari hel chhalkaai jaay, maari chundaldi laheraay...\"]}}]}', `search_text` = 'sakhi marwad javu mari bhari juvani jay \n સખી મારવાડ ઝાવું રે... મારી ભરી ઝુવાની ઝાય \n सखी मारवाड झावुं रे... मारी भरी झुवानी झाय \n old and new evergreen garbas \n navratri garba \n old and new evergreen garbas \n sakhi marwad jaavu re, maari bhari juvaani jaay, \n sakhi marwada na laadka, mane bhaaline seeti maare... \n hoo to paanida bharvaane gai ti re saiyar, \n maari hel chhalkaai jaay, maari chundaldi laheraay... \n સખી મારવાડ જાવું રે, મારી ભરી જુવાની જાય, \n સખી મારવાડાના લાડકા, મને ભાળીને સીટી મારે... \n હું તો પાણીડાં ભરવાને ગઈ’તી રે સૈયર, \n મારી હેલ છલકાઈ જાય, મારી ચૂંદલડી લહેરાય... \n सखी मारवाड जावुं रे, मारी भरी जुवानी जाय, \n सखी मारवाडाना लाडका, मने भाळीने सीटी मारे... \n हूं तो पाणीडां भरवाने गई’ती रे सैयर, \n मारी हेल छलकाई जाय, मारी चूंदलडी लहेराय...' WHERE `id` = 'sakhi-marwad-javu-mari-bhari-juvani-jay-b0bc9bff';

UPDATE `garbas` SET `title` = '{\"en\":\"Tu kali ne kalyani re ma jya jou tya jogmaya\",\"gu\":\"તું કાળી ને કલ્યાણી રે મા\",\"hi\":\"तुं काळी ने कल्याणी रे मा\"}', `lyrics` = '{\"gu\":[\"તું કાળી ને કલ્યાણી રે મા, જ્યાં જોઉં ત્યાં જોગમાયા,\",\"જ્યાં જોઉં ત્યાં જોગમાયા માડી, જ્યાં જોઉં ત્યાં જોગમાયા...\",\"તું પાવા તે ગઢની રાણી રે મા, જ્યાં જોઉં ત્યાં જોગમાયા,\",\"દુઃખડાં દળનારી દુર્ગા રે મા, જ્યાં જોઉં ત્યાં જોગમાયા.\",\"તું આરાસુર અંબા બિરાજે, જ્યાં જોઉં ત્યાં જોગમાયા,\",\"તું બહુચરાજી બાળા રે મા, જ્યાં જોઉં ત્યાં જોગમાયા.\"],\"hi\":[\"तुं काळी ने कल्याणी रे मा, ज्यां जोउं त्यां जोगमाया,\",\"ज्यां जोउं त्यां जोगमाया माडी, ज्यां जोउं त्यां जोगमाया...\",\"तुं पावा ते गढनी राणी रे मा, ज्यां जोउं त्यां जोगमाया,\",\"दुःखडां दळनारी दुर्गा रे मा, ज्यां जोउं त्यां जोगमाया.\",\"तुं आरासुर अंबा बिराजे, ज्यां जोउं त्यां जोगमाया,\",\"तुं बहुचराजी बाळा रे मा, ज्यां जोउं त्यां जोगमाया.\"],\"en\":[\"Tu Kaali ne Kalyaani re Maa, jya jou tya Jogmaaya,\",\"Jya jou tya Jogmaaya maadi, jya jou tya Jogmaaya...\",\"Tu Paava te gadh ni raani re Maa, jya jou tya Jogmaaya,\",\"Dukhada dalnaari Durga re Maa, jya jou tya Jogmaaya.\",\"Tu Aarasur Amba biraaje, jya jou tya Jogmaaya,\",\"Tu Bahucharaji baala re Maa, jya jou tya Jogmaaya.\"],\"sections\":[{\"type\":\"chorus\",\"label\":{\"gu\":\"ધ્રુવપંક્તિ (પલ્લવ)\",\"hi\":\"ध्रुवपंक्ति (पल्लव)\",\"en\":\"REFRAIN\"},\"lines\":{\"gu\":[\"તું કાળી ને કલ્યાણી રે મા, જ્યાં જોઉં ત્યાં જોગમાયા,\",\"જ્યાં જોઉં ત્યાં જોગમાયા માડી, જ્યાં જોઉં ત્યાં જોગમાયા...\"],\"hi\":[\"तुं काळी ने कल्याणी रे मा, ज्यां जोउं त्यां जोगमाया,\",\"ज्यां जोउं त्यां जोगमाया माडी, ज्यां जोउं त्यां जोगमाया...\"],\"en\":[\"Tu Kaali ne Kalyaani re Maa, jya jou tya Jogmaaya,\",\"Jya jou tya Jogmaaya maadi, jya jou tya Jogmaaya...\"]}},{\"type\":\"verse\",\"label\":{\"gu\":\"પાવાગઢ વાસ\",\"hi\":\"पावागढ वास\",\"en\":\"PAVAGADH VERSE\"},\"lines\":{\"gu\":[\"તું પાવા તે ગઢની રાણી રે મા, જ્યાં જોઉં ત્યાં જોગમાયા,\",\"દુઃખડાં દળનારી દુર્ગા રે મા, જ્યાં જોઉં ત્યાં જોગમાયા.\"],\"hi\":[\"तुं पावा ते गढनी राणी रे मा, ज्यां जोउं त्यां जोगमाया,\",\"दुःखडां दळनारी दुर्गा रे मा, ज्यां जोउं त्यां जोगमाया.\"],\"en\":[\"Tu Paava te gadh ni raani re Maa, jya jou tya Jogmaaya,\",\"Dukhada dalnaari Durga re Maa, jya jou tya Jogmaaya.\"]}},{\"type\":\"verse\",\"label\":{\"gu\":\"અંબાજી ને બહુચરાજી\",\"hi\":\"अंबाजी ने बहुचराजी\",\"en\":\"AMBAJI & BAHUCHARAJI VERSE\"},\"lines\":{\"gu\":[\"તું આરાસુર અંબા બિરાજે, જ્યાં જોઉં ત્યાં જોગમાયા,\",\"તું બહુચરાજી બાળા રે મા, જ્યાં જોઉં ત્યાં જોગમાયા.\"],\"hi\":[\"तुं आरासुर अंबा बिराजे, ज्यां जोउं त्यां जोगमाया,\",\"तुं बहुचराजी बाळा रे मा, ज्यां जोउं त्यां जोगमाया.\"],\"en\":[\"Tu Aarasur Amba biraaje, jya jou tya Jogmaaya,\",\"Tu Bahucharaji baala re Maa, jya jou tya Jogmaaya.\"]}}]}', `search_text` = 'tu kali ne kalyani re ma jya jou tya jogmaya \n તું કાળી ને કલ્યાણી રે મા \n तुं काळी ने कल्याणी रे मा \n old and new evergreen garbas \n navratri garba \n old and new evergreen garbas \n tu kaali ne kalyaani re maa, jya jou tya jogmaaya, \n jya jou tya jogmaaya maadi, jya jou tya jogmaaya... \n tu paava te gadh ni raani re maa, jya jou tya jogmaaya, \n dukhada dalnaari durga re maa, jya jou tya jogmaaya. \n તું કાળી ને કલ્યાણી રે મા, જ્યાં જોઉં ત્યાં જોગમાયા, \n જ્યાં જોઉં ત્યાં જોગમાયા માડી, જ્યાં જોઉં ત્યાં જોગમાયા... \n તું પાવા તે ગઢની રાણી રે મા, જ્યાં જોઉં ત્યાં જોગમાયા, \n દુઃખડાં દળનારી દુર્ગા રે મા, જ્યાં જોઉં ત્યાં જોગમાયા. \n तुं काळी ने कल्याणी रे मा, ज्यां जोउं त्यां जोगमाया, \n ज्यां जोउं त्यां जोगमाया माडी, ज्यां जोउं त्यां जोगमाया... \n तुं पावा ते गढनी राणी रे मा, ज्यां जोउं त्यां जोगमाया, \n दुःखडां दळनारी दुर्गा रे मा, ज्यां जोउं त्यां जोगमाया.' WHERE `id` = 'tu-kali-ne-kalyani-re-ma-jya-jou-tya-jogmaya-659bfe94';

UPDATE `garbas` SET `title` = '{\"en\":\"Ma nu leriyu lehray\",\"gu\":\"લીલુડાં રંગ નું લેરીયું રે રંગ લેરીયું રે\",\"hi\":\"लीलुडां रंग नुं लेरीयुं रे रंग लेरीयुं रे\"}', `lyrics` = '{\"gu\":[\"લીલુડાં રંગનું લેરીયું રે રંગ લેરીયું,\",\"માનું લેરીયું લ્હેરાય રે, ગબ્બર ગોખમાં...\",\"રાતી તે ચૂંદડી ને પીળી તે ઓઢણી,\",\"માનું લેરીયું લ્હેરાય રે, શોભે અંબા માવડી...\"],\"hi\":[\"लीलुडां रंगनुं लेरीयुं रे रंग लेरीयुं,\",\"मानुं लेरीयुं ल्हेराय रे, गब्बर गोखमां...\",\"राती ते चूंदडी ने पीळी ते ओढणी,\",\"मानुं लेरीयुं ल्हेराय रे, शोभे अंबा मावडी...\"],\"en\":[\"Leeluda rang nu leriyu re rang leriyu,\",\"Maa nu leriyu lehraay re, Gabbar gokh ma...\",\"Raati te chundadi ne peeli te odhani,\",\"Maa nu leriyu lehraay re, shobhe Amba maavadi...\"],\"sections\":[{\"type\":\"chorus\",\"label\":{\"gu\":\"લેરીયું ધુન\",\"hi\":\"लेरीयुं धुन\",\"en\":\"CHORUS\"},\"lines\":{\"gu\":[\"લીલુડાં રંગનું લેરીયું રે રંગ લેરીયું,\",\"માનું લેરીયું લ્હેરાય રે, ગબ્બર ગોખમાં...\"],\"hi\":[\"लीलुडां रंगनुं लेरीयुं रे रंग लेरीयुं,\",\"मानुं लेरीयुं ल्हेराय रे, गब्बर गोखमां...\"],\"en\":[\"Leeluda rang nu leriyu re rang leriyu,\",\"Maa nu leriyu lehraay re, Gabbar gokh ma...\"]}},{\"type\":\"verse\",\"label\":{\"gu\":\"ચરણ ૧\",\"hi\":\"चरण १\",\"en\":\"VERSE 1\"},\"lines\":{\"gu\":[\"રાતી તે ચૂંદડી ને પીળી તે ઓઢણી,\",\"માનું લેરીયું લ્હેરાય રે, શોભે અંબા માવડી...\"],\"hi\":[\"राती ते चूंदडी ने पीळी ते ओढणी,\",\"मानुं लेरीयुं ल्हेराय रे, शोभे अंबा मावडी...\"],\"en\":[\"Raati te chundadi ne peeli te odhani,\",\"Maa nu leriyu lehraay re, shobhe Amba maavadi...\"]}}]}', `search_text` = 'ma nu leriyu lehray \n લીલુડાં રંગ નું લેરીયું રે રંગ લેરીયું રે \n लीलुडां रंग नुं लेरीयुं रे रंग लेरीयुं रे \n old and new evergreen garbas \n navratri garba \n old and new evergreen garbas \n leeluda rang nu leriyu re rang leriyu, \n maa nu leriyu lehraay re, gabbar gokh ma... \n raati te chundadi ne peeli te odhani, \n maa nu leriyu lehraay re, shobhe amba maavadi... \n લીલુડાં રંગનું લેરીયું રે રંગ લેરીયું, \n માનું લેરીયું લ્હેરાય રે, ગબ્બર ગોખમાં... \n રાતી તે ચૂંદડી ને પીળી તે ઓઢણી, \n માનું લેરીયું લ્હેરાય રે, શોભે અંબા માવડી... \n लीलुडां रंगनुं लेरीयुं रे रंग लेरीयुं, \n मानुं लेरीयुं ल्हेराय रे, गब्बर गोखमां... \n राती ते चूंदडी ने पीळी ते ओढणी, \n मानुं लेरीयुं ल्हेराय रे, शोभे अंबा मावडी...' WHERE `id` = 'ma-nu-leriyu-lehray-7d8f5cd3';

