UPDATE `garbas` SET `title` = '{\"en\":\"Tara re nam no chhedyo aek taro\",\"gu\":\"તારા રે નામનો છેડ્યો એક તારો\",\"hi\":\"तारा रे नामनो छेड्यो एक तारो\"}', `lyrics` = '{\"gu\":[\"તારા રે નામનો છેડ્યો એક તારો\",\"હું તારી મીરા તુ ગીરીધર મારો\",\"આજ નો ચાંદલિયો મને લાગે બહુ વ્હાલો\",\"કહી દો સુરજને કે ઉગે નહીં ઠાલો\",\"આપણે બે અણજાણ્યા પરદેશી પંખી\",\"આજ મળ્યા જુગજુગનો સથવારો ઝંખી\",\"જોજે વિખાય નહીં શમણાનો માળો\",\"કહી દો સુરજને કે ઉગે નહીં ઠાલો\",\"દો રંગી દુનિયાની કેડી કાંટાળી\",\"વસમી છે વાટ કેમ ચાલુ સંભાળી\",\"લાગે ના ઠોકર જો હાથ તમે ઝાલો\",\"કહી દો સુરજને કે ઉગે નહીં ઠાલો\"],\"hi\":[\"तारा रे नामनो छेड्यो एक तारो\",\"हुं तारी मीरा तु गीरीधर मारो\",\"आज नो चांदलियो मने लागे बहु व्हालो\",\"कही दो सुरजने के उगे नहीं ठालो\",\"आपणे बे अणजाण्या परदेशी पंखी\",\"आज मळ्या जुगजुगनो सथवारो झंखी\",\"जोजे विखाय नहीं शमणानो माळो\",\"कही दो सुरजने के उगे नहीं ठालो\",\"दो रंगी दुनियानी केडी कांटाळी\",\"वसमी छे वाट केम चालु संभाळी\",\"लागे ना ठोकर जो हाथ तमे झालो\",\"कही दो सुरजने के उगे नहीं ठालो\"],\"en\":[\"tara te nam no chhedo aek taro hu tari mira tu giridhar maro...\",\"aajno chandaliyo mne bhu vahlo...\",\"kahido suraj ne ke uge nhi thalo...\",\"tara nam ni chundadi aodhi... aek vijogan bhatke chhe... (2)\",\"koi kahe mira koi kahe radha ...\",\"radha sang nam jode chhe...\",\"tara nam ni chundadi aodhi... aek vijogan bhatke chhe... (2)\",\"rah joi bethi jamuna ne kathe...(2)\",\"bandhani jane prem ni gathe...\",\"bandhani ho prem ni gathe...\",\"bethi jamuna kathe...\",\"rah joi bethi jamuna ne kathe...(2)\"],\"sections\":[{\"type\":\"verse\",\"lines\":{\"gu\":[\"તારા રે નામનો છેડ્યો એક તારો\",\"હું તારી મીરા તુ ગીરીધર મારો\",\"આજ નો ચાંદલિયો મને લાગે બહુ વ્હાલો\",\"કહી દો સુરજને કે ઉગે નહીં ઠાલો\",\"આપણે બે અણજાણ્યા પરદેશી પંખી\",\"આજ મળ્યા જુગજુગનો સથવારો ઝંખી\",\"જોજે વિખાય નહીં શમણાનો માળો\",\"કહી દો સુરજને કે ઉગે નહીં ઠાલો\",\"દો રંગી દુનિયાની કેડી કાંટાળી\",\"વસમી છે વાટ કેમ ચાલુ સંભાળી\",\"લાગે ના ઠોકર જો હાથ તમે ઝાલો\",\"કહી દો સુરજને કે ઉગે નહીં ઠાલો\"],\"hi\":[\"तारा रे नामनो छेड्यो एक तारो\",\"हुं तारी मीरा तु गीरीधर मारो\",\"आज नो चांदलियो मने लागे बहु व्हालो\",\"कही दो सुरजने के उगे नहीं ठालो\",\"आपणे बे अणजाण्या परदेशी पंखी\",\"आज मळ्या जुगजुगनो सथवारो झंखी\",\"जोजे विखाय नहीं शमणानो माळो\",\"कही दो सुरजने के उगे नहीं ठालो\",\"दो रंगी दुनियानी केडी कांटाळी\",\"वसमी छे वाट केम चालु संभाळी\",\"लागे ना ठोकर जो हाथ तमे झालो\",\"कही दो सुरजने के उगे नहीं ठालो\"],\"en\":[\"tara te nam no chhedo aek taro hu tari mira tu giridhar maro...\",\"aajno chandaliyo mne bhu vahlo...\",\"kahido suraj ne ke uge nhi thalo...\",\"tara nam ni chundadi aodhi... aek vijogan bhatke chhe... (2)\",\"koi kahe mira koi kahe radha ...\",\"radha sang nam jode chhe...\",\"tara nam ni chundadi aodhi... aek vijogan bhatke chhe... (2)\",\"rah joi bethi jamuna ne kathe...(2)\",\"bandhani jane prem ni gathe...\",\"bandhani ho prem ni gathe...\",\"bethi jamuna kathe...\",\"rah joi bethi jamuna ne kathe...(2)\"]}}]}', `search_text` = 'tara re nam no chhedyo aek taro \n તારા રે નામનો છેડ્યો એક તારો \n तारा रे नामनो छेड्यो एक तारो \n old and new evergreen garbas \n navratri garba \n old and new evergreen garbas \n tara te nam no chhedo aek taro hu tari mira tu giridhar maro... \n aajno chandaliyo mne bhu vahlo... \n kahido suraj ne ke uge nhi thalo... \n tara nam ni chundadi aodhi... aek vijogan bhatke chhe... (2) \n તારા રે નામનો છેડ્યો એક તારો \n હું તારી મીરા તુ ગીરીધર મારો \n આજ નો ચાંદલિયો મને લાગે બહુ વ્હાલો \n કહી દો સુરજને કે ઉગે નહીં ઠાલો \n तारा रे नामनो छेड्यो एक तारो \n हुं तारी मीरा तु गीरीधर मारो \n आज नो चांदलियो मने लागे बहु व्हालो \n कही दो सुरजने के उगे नहीं ठालो' WHERE `id` = 'tara-re-nam-no-chhedyo-aek-taro-1d34acfc';

UPDATE `garbas` SET `title` = '{\"en\":\"Ram rakshastotram\",\"gu\":\"શ્રીરામરક્ષાસ્તોત્ર\",\"hi\":\"श्रीरामरक्षास्तोत्र\"}', `lyrics` = '{\"gu\":[\"॥ શ્રીરામરક્ષાસ્તોત્ર ॥\",\"॥ ૐ શ્રીગણેશાય નમઃ ॥\",\"અસ્ય શ્રીરામરક્ષાસ્તોત્રમન્ત્રસ્ય । બુધકૌશિક ઋષિઃ ।\",\"શ્રીસીતારામચન્દ્રો દેવતા । અનુષ્ટુપ્ છન્દઃ ।\",\"સીતા શક્તિઃ । શ્રીમદ્ હનુમાન કીલકમ્ ।\",\"શ્રીરામચન્દ્રપ્રીત્યર્થે રામરક્ષાસ્તોત્રજપે વિનિયોગઃ ॥\",\"॥ અથ ધ્યાનમ્ ॥\",\"ધ્યાયેદાજાનુબાહું ધૃતશરધનુષં બદ્ધપદ્માસનસ્થમ્ ।\",\"પીતં વાસો વસાનં નવકમલદલસ્પર્ધિનેત્રં પ્રસન્નમ્ ।\",\"વામાઙ્કારૂઢ સીતામુખકમલમિલલ્લોચનં નીરદાભમ્ ।\",\"નાનાલઙ્કારદીપ્તં દધતમુરુજટામણ્ડનં રામચન્દ્રમ્ ॥\",\"॥ ઇતિ ધ્યાનમ્ ॥\",\"ચરિતં રઘુનાથસ્ય શતકોટિ પ્રવિસ્તરમ્ ।\",\"એકૈકમક્ષરં પુંસાં મહાપાતકનાશનમ્ ॥ ૧॥\",\"ધ્યાત્વા નીલોત્પલશ્યામં રામં રાજીવલોચનમ્ ।\",\"જાનકીલક્ષ્મણોપેતં જટામુકુટમણ્ડિતમ્ ॥ ૨॥\",\"સાસિતૂણધનુર્બાણપાણિં નક્તઞ્ચરાન્તકમ્ ।\",\"સ્વલીલયા જગત્રાતું આવિર્ભૂતં અજં વિભુમ્ ॥ ૩॥\",\"રામરક્ષાં પઠેત્પ્રાજ્ઞઃ પાપઘ્નીં સર્વકામદામ્ ।\",\"શિરોમે રાઘવઃ પાતુ ભાલં દશરથાત્મજઃ ॥ ૪॥\",\"કૌસલ્યેયો દૃશૌ પાતુ વિશ્વામિત્રપ્રિયશ્રુતી ।\",\"ઘ્રાણં પાતુ મખત્રાતા મુખં સૌમિત્રિવત્સલઃ ॥ ૫॥\",\"જિવ્હાં વિદ્યાનિધિઃ પાતુ કણ્ઠં ભરતવન્દિતઃ ।\",\"સ્કન્ધૌ દિવ્યાયુધઃ પાતુ ભુજૌ ભગ્નેશકાર્મુકઃ ॥ ૬॥\",\"કરૌ સીતાપતિઃ પાતુ હૃદયં જામદગ્ન્યજિત્ ।\",\"મધ્યં પાતુ ખરધ્વંસી નાભિં જામ્બવદાશ્રયઃ ॥ ૭॥\",\"સુગ્રીવેશઃ કટી પાતુ સક્થિની હનુમત્પ્રભુઃ ।\",\"ઊરૂ રઘૂત્તમઃ પાતુ રક્ષઃકુલવિનાશકૃત્ ॥ ૮॥\",\"જાનુની સેતુકૃત્પાતુ જઙ્ઘે દશમુખાન્તકઃ ।\",\"પાદૌ બિભીષણશ્રીદઃ પાતુ રામોખિલં વપુઃ ॥ ૯॥\",\"એતાં રામબલોપેતાં રક્ષાં યઃ સુકૃતી પઠેત્ ।\",\"સ ચિરાયુઃ સુખી પુત્રી વિજયી વિનયી ભવેત્ ॥ ૧૦॥\",\"પાતાલભૂતલવ્યોમચારિણશ્છદ્મચારિણઃ ।\",\"ન દ્રષ્ટુમપિ શક્તાસ્તે રક્ષિતં રામનામભિઃ ॥ ૧૧॥\",\"રામેતિ રામભદ્રેતિ રામચન્દ્રેતિ વા સ્મરન્ ।\",\"નરો ન લિપ્યતે પાપૈઃ ભુક્તિં મુક્તિં ચ વિન્દતિ ॥ ૧૨॥\",\"જગજૈત્રૈકમન્ત્રેણ રામનામ્નાભિરક્ષિતમ્ ।\",\"યઃ કણ્ઠે ધારયેત્તસ્ય કરસ્થાઃ સર્વસિદ્ધયઃ ॥ ૧૩॥\",\"વજ્રપઞ્જરનામેદં યો રામકવચં સ્મરેત્ ।\",\"અવ્યાહતાજ્ઞઃ સર્વત્ર લભતે જયમઙ્ગલમ્ ॥ ૧૪॥\",\"આદિષ્ટવાન્ યથા સ્વપ્ને રામરક્ષાંમિમાં હરઃ ।\",\"તથા લિખિતવાન્ પ્રાતઃ પ્રબુદ્ધો બુધકૌશિકઃ ॥ ૧૫॥\",\"આરામઃ કલ્પવૃક્ષાણાં વિરામઃ સકલાપદામ્ ।\",\"અભિરામસ્ત્રિલોકાનાં રામઃ શ્રીમાન્ સ નઃ પ્રભુઃ ॥ ૧૬॥\",\"તરુણૌ રૂપસમ્પન્નૌ સુકુમારૌ મહાબલૌ ।\",\"પુણ્ડરીકવિશાલાક્ષૌ ચીરકૃષ્ણાજિનામ્બરૌ ॥ ૧૭॥\",\"ફલમૂલાશિનૌ દાન્તૌ તાપસૌ બ્રહ્મચારિણૌ ।\",\"પુત્રૌ દશરથસ્યૈતૌ ભ્રાતરૌ રામલક્ષ્મણૌ ॥ ૧૮॥\",\"શરણ્યૌ સર્વસત્ત્વાનાં શ્રેષ્ઠૌ સર્વધનુષ્મતામ્ ।\",\"રક્ષઃ કુલનિહન્તારૌ ત્રાયેતાં નો રઘૂત્તમૌ ॥ ૧૯॥\",\"આત્તસજ્જધનુષાવિષુસ્પૃશાવક્ષયાશુગનિષઙ્ગસઙ્ગિનૌ ।\",\"રક્ષણાય મમ રામલક્ષ્મણાવગ્રતઃ પથિ સદૈવ ગચ્છતામ્ ॥ ૨૦॥\",\"સન્નદ્ધઃ કવચી ખડ્ગી ચાપબાણધરો યુવા ।\",\"ગચ્છન્મનોરથોસ્માકં રામઃ પાતુ સલક્ષ્મણઃ ॥ ૨૧॥\",\"રામો દાશરથિઃ શૂરો લક્ષ્મણાનુચરો બલી ।\",\"કાકુત્સ્થઃ પુરુષઃ પૂર્ણઃ કૌસલ્યેયો રઘુત્તમઃ ॥ ૨૨॥\",\"વેદાન્તવેદ્યો યજ્ઞેશઃ પુરાણપુરુષોત્તમઃ ।\",\"જાનકીવલ્લભઃ શ્રીમાન્ અપ્રમેય પરાક્રમઃ ॥ ૨૩॥\",\"ઇત્યેતાનિ જપન્નિત્યં મદ્ભક્તઃ શ્રદ્ધયાન્વિતઃ ।\",\"અશ્વમેધાધિકં પુણ્યં સમ્પ્રાપ્નોતિ ન સંશયઃ ॥ ૨૪॥\",\"રામં દુર્વાદલશ્યામં પદ્માક્ષં પીતવાસસમ્ ।\",\"સ્તુવન્તિ નામભિર્દિવ્યૈઃ ન તે સંસારિણો નરઃ ॥ ૨૫॥\",\"રામં લક્ષ્મણપૂર્વજં રઘુવરં સીતાપતિં સુન્દરમ્ ।\",\"કાકુત્સ્થં કરુણાર્ણવં ગુણનિધિં વિપ્રપ્રિયં ધાર્મિકમ્ ।\",\"રાજેન્દ્રં સત્યસન્ધં દશરથતનયં શ્યામલં શાન્તમૂર્તિમ્ ।\",\"વન્દે લોકાભિરામં રઘુકુલતિલકં રાઘવં રાવણારિમ્ ॥ ૨૬॥\",\"રામાય રામભદ્રાય રામચન્દ્રાય વેધસે ।\",\"રઘુનાથાય નાથાય સીતાયાઃ પતયે નમઃ ॥ ૨૭॥\",\"શ્રીરામ રામ રઘુનન્દન રામ રામ ।\",\"શ્રીરામ રામ ભરતાગ્રજ રામ રામ ।\",\"શ્રીરામ રામ રણકર્કશ રામ રામ ।\",\"શ્રીરામ રામ શરણં ભવ રામ રામ ॥ ૨૮॥\",\"શ્રીરામચન્દ્રચરણૌ મનસા સ્મરામિ ।\",\"શ્રીરામચન્દ્રચરણૌ વચસા ગૃણામિ ।\",\"શ્રીરામચન્દ્રચરણૌ શિરસા નમામિ ।\",\"શ્રીરામચન્દ્રચરણૌ શરણં પ્રપદ્યે ॥ ૨૯॥\",\"માતા રામો મત્પિતા રામચન્દ્રઃ ।\",\"સ્વામી રામો મત્સખા રામચન્દ્રઃ ।\",\"સર્વસ્વં મે રામચન્દ્રો દયાલુઃ ।\",\"નાન્યં જાને નૈવ જાને ન જાને ॥ ૩૦॥\",\"દક્ષિણે લક્ષ્મણો યસ્ય વામે તુ જનકાત્મજા ।\",\"પુરતો મારુતિર્યસ્ય તં વન્દે રઘુનન્દનમ્ ॥ ૩૧॥\",\"લોકાભિરામં રણરઙ્ગધીરમ્ ।\",\"રાજીવનેત્રં રઘુવંશનાથમ્ ।\",\"કારુણ્યરૂપં કરુણાકરં તમ્ ।\",\"શ્રીરામચન્દ્રમ્ શરણં પ્રપદ્યે ॥ ૩૨॥\",\"મનોજવં મારુતતુલ્યવેગમ્ ।\",\"જિતેન્દ્રિયં બુદ્ધિમતાં વરિષ્ઠમ્ ।\",\"વાતાત્મજં વાનરયૂથમુખ્યમ્ ।\",\"શ્રીરામદૂતં શરણં પ્રપદ્યે ॥ ૩૩॥\",\"કૂજન્તં રામ રામેતિ મધુરં મધુરાક્ષરમ્ ।\",\"આરુહ્ય કવિતાશાખાં વન્દે વાલ્મીકિકોકિલમ્ ॥ ૩૪॥\",\"આપદાં અપહર્તારં દાતારં સર્વસમ્પદામ્ ।\",\"લોકાભિરામં શ્રીરામં ભૂયો ભૂયો નમામ્યહમ્ ॥ ૩૫॥\",\"ભર્જનં ભવબીજાનાં અર્જનં સુખસમ્પદામ્ ।\",\"તર્જનં યમદૂતાનાં રામ રામેતિ ગર્જનમ્ ॥ ૩૬॥\",\"રામો રાજમણિઃ સદા વિજયતે રામં રમેશં ભજે ।\",\"રામેણાભિહતા નિશાચરચમૂ રામાય તસ્મૈ નમઃ ।\",\"રામાન્નાસ્તિ પરાયણં પરતરં રામસ્ય દાસોસ્મ્યહમ્ ।\",\"રામે ચિત્તલયઃ સદા ભવતુ મે ભો રામ મામુદ્ધર ॥ ૩૭॥\",\"રામ રામેતિ રામેતિ રમે રામે મનોરમે ।\",\"સહસ્રનામ તત્તુલ્યં રામનામ વરાનને ॥ ૩૮॥\",\"ઇતિ શ્રીબુધકૌશિકવિરચિતં શ્રીરામરક્ષાસ્તોત્રં સમ્પૂર્ણમ્ ॥\",\"॥ શ્રીસીતારામચન્દ્રાર્પણમસ્તુ ॥\"],\"hi\":[\"॥ श्रीरामरक्षास्तोत्र ॥\",\"॥ ॐ श्रीगणेशाय नमः ॥\",\"अस्य श्रीरामरक्षास्तोत्रमन्त्रस्य । बुधकौशिक ऋषिः ।\",\"श्रीसीतारामचन्द्रो देवता । अनुष्टुप् छन्दः ।\",\"सीता शक्तिः । श्रीमद् हनुमान कीलकम् ।\",\"श्रीरामचन्द्रप्रीत्यर्थे रामरक्षास्तोत्रजपे विनियोगः ॥\",\"॥ अथ ध्यानम् ॥\",\"ध्यायेदाजानुबाहुं धृतशरधनुषं बद्धपद्मासनस्थम् ।\",\"पीतं वासो वसानं नवकमलदलस्पर्धिनेत्रं प्रसन्नम् ।\",\"वामाङ्कारूढ सीतामुखकमलमिलल्लोचनं नीरदाभम् ।\",\"नानालङ्कारदीप्तं दधतमुरुजटामण्डनं रामचन्द्रम् ॥\",\"॥ इति ध्यानम् ॥\",\"चरितं रघुनाथस्य शतकोटि प्रविस्तरम् ।\",\"एकैकमक्षरं पुंसां महापातकनाशनम् ॥ १॥\",\"ध्यात्वा नीलोत्पलश्यामं रामं राजीवलोचनम् ।\",\"जानकीलक्ष्मणोपेतं जटामुकुटमण्डितम् ॥ २॥\",\"सासितूणधनुर्बाणपाणिं नक्तञ्चरान्तकम् ।\",\"स्वलीलया जगत्रातुं आविर्भूतं अजं विभुम् ॥ ३॥\",\"रामरक्षां पठेत्प्राज्ञः पापघ्नीं सर्वकामदाम् ।\",\"शिरोमे राघवः पातु भालं दशरथात्मजः ॥ ४॥\",\"कौसल्येयो दृशौ पातु विश्वामित्रप्रियश्रुती ।\",\"घ्राणं पातु मखत्राता मुखं सौमित्रिवत्सलः ॥ ५॥\",\"जिव्हां विद्यानिधिः पातु कण्ठं भरतवन्दितः ।\",\"स्कन्धौ दिव्यायुधः पातु भुजौ भग्नेशकार्मुकः ॥ ६॥\",\"करौ सीतापतिः पातु हृदयं जामदग्न्यजित् ।\",\"मध्यं पातु खरध्वंसी नाभिं जाम्बवदाश्रयः ॥ ७॥\",\"सुग्रीवेशः कटी पातु सक्थिनी हनुमत्प्रभुः ।\",\"ऊरू रघूत्तमः पातु रक्षःकुलविनाशकृत् ॥ ८॥\",\"जानुनी सेतुकृत्पातु जङ्घे दशमुखान्तकः ।\",\"पादौ बिभीषणश्रीदः पातु रामोखिलं वपुः ॥ ९॥\",\"एतां रामबलोपेतां रक्षां यः सुकृती पठेत् ।\",\"स चिरायुः सुखी पुत्री विजयी विनयी भवेत् ॥ १०॥\",\"पातालभूतलव्योमचारिणश्छद्मचारिणः ।\",\"न द्रष्टुमपि शक्तास्ते रक्षितं रामनामभिः ॥ ११॥\",\"रामेति रामभद्रेति रामचन्द्रेति वा स्मरन् ।\",\"नरो न लिप्यते पापैः भुक्तिं मुक्तिं च विन्दति ॥ १२॥\",\"जगजैत्रैकमन्त्रेण रामनाम्नाभिरक्षितम् ।\",\"यः कण्ठे धारयेत्तस्य करस्थाः सर्वसिद्धयः ॥ १३॥\",\"वज्रपञ्जरनामेदं यो रामकवचं स्मरेत् ।\",\"अव्याहताज्ञः सर्वत्र लभते जयमङ्गलम् ॥ १४॥\",\"आदिष्टवान् यथा स्वप्ने रामरक्षांमिमां हरः ।\",\"तथा लिखितवान् प्रातः प्रबुद्धो बुधकौशिकः ॥ १५॥\",\"आरामः कल्पवृक्षाणां विरामः सकलापदाम् ।\",\"अभिरामस्त्रिलोकानां रामः श्रीमान् स नः प्रभुः ॥ १६॥\",\"तरुणौ रूपसम्पन्नौ सुकुमारौ महाबलौ ।\",\"पुण्डरीकविशालाक्षौ चीरकृष्णाजिनाम्बरौ ॥ १७॥\",\"फलमूलाशिनौ दान्तौ तापसौ ब्रह्मचारिणौ ।\",\"पुत्रौ दशरथस्यैतौ भ्रातरौ रामलक्ष्मणौ ॥ १८॥\",\"शरण्यौ सर्वसत्त्वानां श्रेष्ठौ सर्वधनुष्मताम् ।\",\"रक्षः कुलनिहन्तारौ त्रायेतां नो रघूत्तमौ ॥ १९॥\",\"आत्तसज्जधनुषाविषुस्पृशावक्षयाशुगनिषङ्गसङ्गिनौ ।\",\"रक्षणाय मम रामलक्ष्मणावग्रतः पथि सदैव गच्छताम् ॥ २०॥\",\"सन्नद्धः कवची खड्गी चापबाणधरो युवा ।\",\"गच्छन्मनोरथोस्माकं रामः पातु सलक्ष्मणः ॥ २१॥\",\"रामो दाशरथिः शूरो लक्ष्मणानुचरो बली ।\",\"काकुत्स्थः पुरुषः पूर्णः कौसल्येयो रघुत्तमः ॥ २२॥\",\"वेदान्तवेद्यो यज्ञेशः पुराणपुरुषोत्तमः ।\",\"जानकीवल्लभः श्रीमान् अप्रमेय पराक्रमः ॥ २३॥\",\"इत्येतानि जपन्नित्यं मद्भक्तः श्रद्धयान्वितः ।\",\"अश्वमेधाधिकं पुण्यं सम्प्राप्नोति न संशयः ॥ २४॥\",\"रामं दुर्वादलश्यामं पद्माक्षं पीतवाससम् ।\",\"स्तुवन्ति नामभिर्दिव्यैः न ते संसारिणो नरः ॥ २५॥\",\"रामं लक्ष्मणपूर्वजं रघुवरं सीतापतिं सुन्दरम् ।\",\"काकुत्स्थं करुणार्णवं गुणनिधिं विप्रप्रियं धार्मिकम् ।\",\"राजेन्द्रं सत्यसन्धं दशरथतनयं श्यामलं शान्तमूर्तिम् ।\",\"वन्दे लोकाभिरामं रघुकुलतिलकं राघवं रावणारिम् ॥ २६॥\",\"रामाय रामभद्राय रामचन्द्राय वेधसे ।\",\"रघुनाथाय नाथाय सीतायाः पतये नमः ॥ २७॥\",\"श्रीराम राम रघुनन्दन राम राम ।\",\"श्रीराम राम भरताग्रज राम राम ।\",\"श्रीराम राम रणकर्कश राम राम ।\",\"श्रीराम राम शरणं भव राम राम ॥ २८॥\",\"श्रीरामचन्द्रचरणौ मनसा स्मरामि ।\",\"श्रीरामचन्द्रचरणौ वचसा गृणामि ।\",\"श्रीरामचन्द्रचरणौ शिरसा नमामि ।\",\"श्रीरामचन्द्रचरणौ शरणं प्रपद्ये ॥ २९॥\",\"माता रामो मत्पिता रामचन्द्रः ।\",\"स्वामी रामो मत्सखा रामचन्द्रः ।\",\"सर्वस्वं मे रामचन्द्रो दयालुः ।\",\"नान्यं जाने नैव जाने न जाने ॥ ३०॥\",\"दक्षिणे लक्ष्मणो यस्य वामे तु जनकात्मजा ।\",\"पुरतो मारुतिर्यस्य तं वन्दे रघुनन्दनम् ॥ ३१॥\",\"लोकाभिरामं रणरङ्गधीरम् ।\",\"राजीवनेत्रं रघुवंशनाथम् ।\",\"कारुण्यरूपं करुणाकरं तम् ।\",\"श्रीरामचन्द्रम् शरणं प्रपद्ये ॥ ३२॥\",\"मनोजवं मारुततुल्यवेगम् ।\",\"जितेन्द्रियं बुद्धिमतां वरिष्ठम् ।\",\"वातात्मजं वानरयूथमुख्यम् ।\",\"श्रीरामदूतं शरणं प्रपद्ये ॥ ३३॥\",\"कूजन्तं राम रामेति मधुरं मधुराक्षरम् ।\",\"आरुह्य कविताशाखां वन्दे वाल्मीकिकोकिलम् ॥ ३४॥\",\"आपदां अपहर्तारं दातारं सर्वसम्पदाम् ।\",\"लोकाभिरामं श्रीरामं भूयो भूयो नमाम्यहम् ॥ ३५॥\",\"भर्जनं भवबीजानां अर्जनं सुखसम्पदाम् ।\",\"तर्जनं यमदूतानां राम रामेति गर्जनम् ॥ ३६॥\",\"रामो राजमणिः सदा विजयते रामं रमेशं भजे ।\",\"रामेणाभिहता निशाचरचमू रामाय तस्मै नमः ।\",\"रामान्नास्ति परायणं परतरं रामस्य दासोस्म्यहम् ।\",\"रामे चित्तलयः सदा भवतु मे भो राम मामुद्धर ॥ ३७॥\",\"राम रामेति रामेति रमे रामे मनोरमे ।\",\"सहस्रनाम तत्तुल्यं रामनाम वरानने ॥ ३८॥\",\"इति श्रीबुधकौशिकविरचितं श्रीरामरक्षास्तोत्रं सम्पूर्णम् ॥\",\"॥ श्रीसीतारामचन्द्रार्पणमस्तु ॥\"],\"en\":[\". sriramaraksastotra.\",\". \'om sriganesaya namah.\",\"asya sriramaraksastotramantrasya. budhakausika rsih.\",\"srisitaramacandro devata. anustup chandah.\",\"sita saktih. srimad hanumana kilakam.\",\"sriramacandraprityarthe ramaraksastotrajape viniyogah.\",\". atha dhyanam.\",\"dhyayedajanubahum dhrtasaradhanusam bad\'dhapadmasanastham.\",\"pitam vaso vasanam navakamaladalaspardhinetram prasannam.\",\"vamankarudha sitamukhakamalamilallocanam niradabham.\",\"nanalankaradiptam dadhatamurujatamandanam ramacandram.\",\". iti dhyanam.\",\"caritam raghunathasya satakoti pravistaram.\",\"ekaikamaksaram punsam mahapatakanasanam. 1.\",\"dhyatva nilotpalasyamam ramam rajivalocanam.\",\"janakilaksmanopetam jatamukutamanditam. 2.\",\"sasitunadhanurbanapanim naktancarantakam.\",\"svalilaya jagatratum avirbhutam ajam vibhum. 3.\",\"ramaraksam pathetprajnah papaghnim sarvakamadam.\",\"sirome raghavah patu bhalam dasarathatmajah. 4.\",\"kausalyeyo drsau patu visvamitrapriyasruti.\",\"ghranam patu makhatrata mukham saumitrivatsalah. 5.\",\"jivham vidyanidhih patu kantham bharatavanditah.\",\"skandhau divyayudhah patu bhujau bhagnesakarmukah. 6.\",\"karau sitapatih patu hrdayam jamadagn\'yajit.\",\"madhyam patu kharadhvansi nabhim jambavadasrayah. 7.\",\"sugrivesah kati patu sakthini hanumatprabhuh.\",\"uru raghuttamah patu raksahkulavinasakrt. 8.\",\"januni setukrtpatu janghe dasamukhantakah.\",\"padau bibhisanasridah patu ramokhilam vapuh. 9.\",\"etam ramabalopetam raksam yah sukrti pathet.\",\"sa cirayuh sukhi putri vijayi vinayi bhavet. 10.\",\"patalabhutalavyomacarinaschadmacarinah.\",\"na drastumapi saktaste raksitam ramanamabhih. 11.\",\"rameti ramabhadreti ramacandreti va smaran.\",\"naro na lipyate papaih bhuktim muktim ca vindati. 12.\",\"jagajaitraikamantrena ramanamnabhiraksitam.\",\"yah kanthe dharayettasya karasthah sarvasid\'dhayah. 13.\",\"vajrapanjaranamedam yo ramakavacam smaret.\",\"avyahatajnah sarvatra labhate jayamangalam. 14.\",\"adistavan yatha svapne ramaraksammimam harah.\",\"tatha likhitavan pratah prabud\'dho budhakausikah. 15.\",\"aramah kalpavrksanam viramah sakalapadam.\",\"abhiramastrilokanam ramah sriman sa nah prabhuh. 16.\",\"tarunau rupasampannau sukumarau mahabalau.\",\"pundarikavisalaksau cirakrsnajinambarau. 17.\",\"phalamulasinau dantau tapasau brahmacarinau.\",\"putrau dasarathasyaitau bhratarau ramalaksmanau. 18.\",\"saranyau sarvasattvanam sresthau sarvadhanusmatam.\",\"raksah kulanihantarau trayetam no raghuttamau. 1 9.\",\"attasajjadhanusavisusprsavaksayasuganisangasanginau.\",\"raksanaya mama ramalaksmanavagratah pathi sadaiva gacchatam. 20.\",\"sannad\'dhah kavaci khadgi capabanadharo yuva.\",\"gacchanmanorathosmakam ramah patu salaksmanah. 21.\",\"ramo dasarathih suro laksmananucaro bali.\",\"kakutsthah purusah purnah kausalyeyo raghuttamah. 22.\",\"vedantavedyo yajnesah puranapurusottamah.\",\"janakivallabhah sriman aprameya parakramah. 23.\",\"ityetani japannityam madbhaktah srad\'dhayanvitah.\",\"asvamedhadhikam punyam samprapnoti na sansayah. 24.\",\"ramam durvadalasyamam padmaksam pitavasasam.\",\"stuvanti namabhirdivyaih na te sansarino narah. 25.\",\"ramam laksmanapurvajam raghuvaram sitapatim sundaram.\",\"kakutstham karunarnavam gunanidhim viprapriyam dharmikam.\",\"rajendram satyasandham dasarathatanayam syamalam santamurtim.\",\"vande lokabhiramam raghukulatilakam raghavam ravanarim. 26.\",\"ramaya ramabhadraya ramacandraya vedhase.\",\"raghunathaya nathaya sitayah pataye namah. 27.\",\"srirama rama raghunandana rama rama.\",\"srirama rama bharatagraja rama rama.\",\"srirama rama ranakarkasa rama rama.\",\"srirama rama saranam bhava rama rama. 28.\",\"sriramacandracaranau manasa smarami.\",\"sriramacandracaranau vacasa grnami.\",\"sriramacandracaranau sirasa namami.\",\"sriramacandracaranau saranam prapadye. 2 9.\",\"mata ramo matpita ramacandrah.\",\"svami ramo matsakha ramacandrah.\",\"sarvasvam me ramacandro dayaluh.\",\"nan\'yam jane naiva jane na jane. 30.\",\"daksine laksmano yasya vame tu janakatmaja.\",\"purato marutiryasya tam vande raghunandanam. 31.\",\"lokabhiramam ranarangadhiram.\",\"rajivanetram raghuvansanatham.\",\"karunyarupam karunakaram tam.\",\"sriramacandram saranam prapadye. 32.\",\"manojavam marutatulyavegam.\",\"jitendriyam bud\'dhimatam varistham.\",\"vatatmajam vanarayuthamukhyam.\",\"sriramadutam saranam prapadye. 33.\",\"kujantam rama rameti madhuram madhuraksaram.\",\"aruhya kavitasakham vande valmikikokilam. 34.\",\"apadam apahartaram dataram sarvasampadam.\",\"lokabhiramam sriramam bhuyo bhuyo namamyaham. 35.\",\"bharjanam bhavabijanam arjanam sukhasampadam.\",\"tarjanam yamadutanam rama rameti garjanam. 36.\",\"ramo rajamanih sada vijayate ramam ramesam bhaje.\",\"ramenabhihata nisacaracamu ramaya tasmai namah.\",\"ramannasti parayanam parataram ramasya dasosmyaham.\",\"rame cittalayah sada bhavatu me bho rama mamud\'dhara. 37.\",\"rama rameti rameti rame rame manorame.\",\"sahasranama tattulyam ramanama varanane. 38.\",\"iti sribudhakausikaviracitam sriramaraksastotram sampurnam.\",\". srisitaramacandrarpanamastu.\"],\"sections\":[{\"type\":\"verse\",\"lines\":{\"gu\":[\"॥ શ્રીરામરક્ષાસ્તોત્ર ॥\"],\"hi\":[\"॥ श्रीरामरक्षास्तोत्र ॥\"],\"en\":[\". sriramaraksastotra.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"॥ ૐ શ્રીગણેશાય નમઃ ॥\"],\"hi\":[\"॥ ॐ श्रीगणेशाय नमः ॥\"],\"en\":[\". \'om sriganesaya namah.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"અસ્ય શ્રીરામરક્ષાસ્તોત્રમન્ત્રસ્ય । બુધકૌશિક ઋષિઃ ।\",\"શ્રીસીતારામચન્દ્રો દેવતા । અનુષ્ટુપ્ છન્દઃ ।\",\"સીતા શક્તિઃ । શ્રીમદ્ હનુમાન કીલકમ્ ।\",\"શ્રીરામચન્દ્રપ્રીત્યર્થે રામરક્ષાસ્તોત્રજપે વિનિયોગઃ ॥\"],\"hi\":[\"अस्य श्रीरामरक्षास्तोत्रमन्त्रस्य । बुधकौशिक ऋषिः ।\",\"श्रीसीतारामचन्द्रो देवता । अनुष्टुप् छन्दः ।\",\"सीता शक्तिः । श्रीमद् हनुमान कीलकम् ।\",\"श्रीरामचन्द्रप्रीत्यर्थे रामरक्षास्तोत्रजपे विनियोगः ॥\"],\"en\":[\"asya sriramaraksastotramantrasya. budhakausika rsih.\",\"srisitaramacandro devata. anustup chandah.\",\"sita saktih. srimad hanumana kilakam.\",\"sriramacandraprityarthe ramaraksastotrajape viniyogah.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"॥ અથ ધ્યાનમ્ ॥\"],\"hi\":[\"॥ अथ ध्यानम् ॥\"],\"en\":[\". atha dhyanam.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"ધ્યાયેદાજાનુબાહું ધૃતશરધનુષં બદ્ધપદ્માસનસ્થમ્ ।\",\"પીતં વાસો વસાનં નવકમલદલસ્પર્ધિનેત્રં પ્રસન્નમ્ ।\",\"વામાઙ્કારૂઢ સીતામુખકમલમિલલ્લોચનં નીરદાભમ્ ।\",\"નાનાલઙ્કારદીપ્તં દધતમુરુજટામણ્ડનં રામચન્દ્રમ્ ॥\"],\"hi\":[\"ध्यायेदाजानुबाहुं धृतशरधनुषं बद्धपद्मासनस्थम् ।\",\"पीतं वासो वसानं नवकमलदलस्पर्धिनेत्रं प्रसन्नम् ।\",\"वामाङ्कारूढ सीतामुखकमलमिलल्लोचनं नीरदाभम् ।\",\"नानालङ्कारदीप्तं दधतमुरुजटामण्डनं रामचन्द्रम् ॥\"],\"en\":[\"dhyayedajanubahum dhrtasaradhanusam bad\'dhapadmasanastham.\",\"pitam vaso vasanam navakamaladalaspardhinetram prasannam.\",\"vamankarudha sitamukhakamalamilallocanam niradabham.\",\"nanalankaradiptam dadhatamurujatamandanam ramacandram.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"॥ ઇતિ ધ્યાનમ્ ॥\"],\"hi\":[\"॥ इति ध्यानम् ॥\"],\"en\":[\". iti dhyanam.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"ચરિતં રઘુનાથસ્ય શતકોટિ પ્રવિસ્તરમ્ ।\",\"એકૈકમક્ષરં પુંસાં મહાપાતકનાશનમ્ ॥ ૧॥\"],\"hi\":[\"चरितं रघुनाथस्य शतकोटि प्रविस्तरम् ।\",\"एकैकमक्षरं पुंसां महापातकनाशनम् ॥ १॥\"],\"en\":[\"caritam raghunathasya satakoti pravistaram.\",\"ekaikamaksaram punsam mahapatakanasanam. 1.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"ધ્યાત્વા નીલોત્પલશ્યામં રામં રાજીવલોચનમ્ ।\",\"જાનકીલક્ષ્મણોપેતં જટામુકુટમણ્ડિતમ્ ॥ ૨॥\"],\"hi\":[\"ध्यात्वा नीलोत्पलश्यामं रामं राजीवलोचनम् ।\",\"जानकीलक्ष्मणोपेतं जटामुकुटमण्डितम् ॥ २॥\"],\"en\":[\"dhyatva nilotpalasyamam ramam rajivalocanam.\",\"janakilaksmanopetam jatamukutamanditam. 2.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"સાસિતૂણધનુર્બાણપાણિં નક્તઞ્ચરાન્તકમ્ ।\",\"સ્વલીલયા જગત્રાતું આવિર્ભૂતં અજં વિભુમ્ ॥ ૩॥\"],\"hi\":[\"सासितूणधनुर्बाणपाणिं नक्तञ्चरान्तकम् ।\",\"स्वलीलया जगत्रातुं आविर्भूतं अजं विभुम् ॥ ३॥\"],\"en\":[\"sasitunadhanurbanapanim naktancarantakam.\",\"svalilaya jagatratum avirbhutam ajam vibhum. 3.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"રામરક્ષાં પઠેત્પ્રાજ્ઞઃ પાપઘ્નીં સર્વકામદામ્ ।\",\"શિરોમે રાઘવઃ પાતુ ભાલં દશરથાત્મજઃ ॥ ૪॥\"],\"hi\":[\"रामरक्षां पठेत्प्राज्ञः पापघ्नीं सर्वकामदाम् ।\",\"शिरोमे राघवः पातु भालं दशरथात्मजः ॥ ४॥\"],\"en\":[\"ramaraksam pathetprajnah papaghnim sarvakamadam.\",\"sirome raghavah patu bhalam dasarathatmajah. 4.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"કૌસલ્યેયો દૃશૌ પાતુ વિશ્વામિત્રપ્રિયશ્રુતી ।\",\"ઘ્રાણં પાતુ મખત્રાતા મુખં સૌમિત્રિવત્સલઃ ॥ ૫॥\"],\"hi\":[\"कौसल्येयो दृशौ पातु विश्वामित्रप्रियश्रुती ।\",\"घ्राणं पातु मखत्राता मुखं सौमित्रिवत्सलः ॥ ५॥\"],\"en\":[\"kausalyeyo drsau patu visvamitrapriyasruti.\",\"ghranam patu makhatrata mukham saumitrivatsalah. 5.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"જિવ્હાં વિદ્યાનિધિઃ પાતુ કણ્ઠં ભરતવન્દિતઃ ।\",\"સ્કન્ધૌ દિવ્યાયુધઃ પાતુ ભુજૌ ભગ્નેશકાર્મુકઃ ॥ ૬॥\"],\"hi\":[\"जिव्हां विद्यानिधिः पातु कण्ठं भरतवन्दितः ।\",\"स्कन्धौ दिव्यायुधः पातु भुजौ भग्नेशकार्मुकः ॥ ६॥\"],\"en\":[\"jivham vidyanidhih patu kantham bharatavanditah.\",\"skandhau divyayudhah patu bhujau bhagnesakarmukah. 6.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"કરૌ સીતાપતિઃ પાતુ હૃદયં જામદગ્ન્યજિત્ ।\",\"મધ્યં પાતુ ખરધ્વંસી નાભિં જામ્બવદાશ્રયઃ ॥ ૭॥\"],\"hi\":[\"करौ सीतापतिः पातु हृदयं जामदग्न्यजित् ।\",\"मध्यं पातु खरध्वंसी नाभिं जाम्बवदाश्रयः ॥ ७॥\"],\"en\":[\"karau sitapatih patu hrdayam jamadagn\'yajit.\",\"madhyam patu kharadhvansi nabhim jambavadasrayah. 7.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"સુગ્રીવેશઃ કટી પાતુ સક્થિની હનુમત્પ્રભુઃ ।\",\"ઊરૂ રઘૂત્તમઃ પાતુ રક્ષઃકુલવિનાશકૃત્ ॥ ૮॥\"],\"hi\":[\"सुग्रीवेशः कटी पातु सक्थिनी हनुमत्प्रभुः ।\",\"ऊरू रघूत्तमः पातु रक्षःकुलविनाशकृत् ॥ ८॥\"],\"en\":[\"sugrivesah kati patu sakthini hanumatprabhuh.\",\"uru raghuttamah patu raksahkulavinasakrt. 8.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"જાનુની સેતુકૃત્પાતુ જઙ્ઘે દશમુખાન્તકઃ ।\",\"પાદૌ બિભીષણશ્રીદઃ પાતુ રામોખિલં વપુઃ ॥ ૯॥\"],\"hi\":[\"जानुनी सेतुकृत्पातु जङ्घे दशमुखान्तकः ।\",\"पादौ बिभीषणश्रीदः पातु रामोखिलं वपुः ॥ ९॥\"],\"en\":[\"januni setukrtpatu janghe dasamukhantakah.\",\"padau bibhisanasridah patu ramokhilam vapuh. 9.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"એતાં રામબલોપેતાં રક્ષાં યઃ સુકૃતી પઠેત્ ।\",\"સ ચિરાયુઃ સુખી પુત્રી વિજયી વિનયી ભવેત્ ॥ ૧૦॥\"],\"hi\":[\"एतां रामबलोपेतां रक्षां यः सुकृती पठेत् ।\",\"स चिरायुः सुखी पुत्री विजयी विनयी भवेत् ॥ १०॥\"],\"en\":[\"etam ramabalopetam raksam yah sukrti pathet.\",\"sa cirayuh sukhi putri vijayi vinayi bhavet. 10.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"પાતાલભૂતલવ્યોમચારિણશ્છદ્મચારિણઃ ।\",\"ન દ્રષ્ટુમપિ શક્તાસ્તે રક્ષિતં રામનામભિઃ ॥ ૧૧॥\"],\"hi\":[\"पातालभूतलव्योमचारिणश्छद्मचारिणः ।\",\"न द्रष्टुमपि शक्तास्ते रक्षितं रामनामभिः ॥ ११॥\"],\"en\":[\"patalabhutalavyomacarinaschadmacarinah.\",\"na drastumapi saktaste raksitam ramanamabhih. 11.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"રામેતિ રામભદ્રેતિ રામચન્દ્રેતિ વા સ્મરન્ ।\",\"નરો ન લિપ્યતે પાપૈઃ ભુક્તિં મુક્તિં ચ વિન્દતિ ॥ ૧૨॥\"],\"hi\":[\"रामेति रामभद्रेति रामचन्द्रेति वा स्मरन् ।\",\"नरो न लिप्यते पापैः भुक्तिं मुक्तिं च विन्दति ॥ १२॥\"],\"en\":[\"rameti ramabhadreti ramacandreti va smaran.\",\"naro na lipyate papaih bhuktim muktim ca vindati. 12.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"જગજૈત્રૈકમન્ત્રેણ રામનામ્નાભિરક્ષિતમ્ ।\",\"યઃ કણ્ઠે ધારયેત્તસ્ય કરસ્થાઃ સર્વસિદ્ધયઃ ॥ ૧૩॥\"],\"hi\":[\"जगजैत्रैकमन्त्रेण रामनाम्नाभिरक्षितम् ।\",\"यः कण्ठे धारयेत्तस्य करस्थाः सर्वसिद्धयः ॥ १३॥\"],\"en\":[\"jagajaitraikamantrena ramanamnabhiraksitam.\",\"yah kanthe dharayettasya karasthah sarvasid\'dhayah. 13.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"વજ્રપઞ્જરનામેદં યો રામકવચં સ્મરેત્ ।\",\"અવ્યાહતાજ્ઞઃ સર્વત્ર લભતે જયમઙ્ગલમ્ ॥ ૧૪॥\"],\"hi\":[\"वज्रपञ्जरनामेदं यो रामकवचं स्मरेत् ।\",\"अव्याहताज्ञः सर्वत्र लभते जयमङ्गलम् ॥ १४॥\"],\"en\":[\"vajrapanjaranamedam yo ramakavacam smaret.\",\"avyahatajnah sarvatra labhate jayamangalam. 14.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"આદિષ્ટવાન્ યથા સ્વપ્ને રામરક્ષાંમિમાં હરઃ ।\",\"તથા લિખિતવાન્ પ્રાતઃ પ્રબુદ્ધો બુધકૌશિકઃ ॥ ૧૫॥\"],\"hi\":[\"आदिष्टवान् यथा स्वप्ने रामरक्षांमिमां हरः ।\",\"तथा लिखितवान् प्रातः प्रबुद्धो बुधकौशिकः ॥ १५॥\"],\"en\":[\"adistavan yatha svapne ramaraksammimam harah.\",\"tatha likhitavan pratah prabud\'dho budhakausikah. 15.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"આરામઃ કલ્પવૃક્ષાણાં વિરામઃ સકલાપદામ્ ।\",\"અભિરામસ્ત્રિલોકાનાં રામઃ શ્રીમાન્ સ નઃ પ્રભુઃ ॥ ૧૬॥\"],\"hi\":[\"आरामः कल्पवृक्षाणां विरामः सकलापदाम् ।\",\"अभिरामस्त्रिलोकानां रामः श्रीमान् स नः प्रभुः ॥ १६॥\"],\"en\":[\"aramah kalpavrksanam viramah sakalapadam.\",\"abhiramastrilokanam ramah sriman sa nah prabhuh. 16.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"તરુણૌ રૂપસમ્પન્નૌ સુકુમારૌ મહાબલૌ ।\",\"પુણ્ડરીકવિશાલાક્ષૌ ચીરકૃષ્ણાજિનામ્બરૌ ॥ ૧૭॥\"],\"hi\":[\"तरुणौ रूपसम्पन्नौ सुकुमारौ महाबलौ ।\",\"पुण्डरीकविशालाक्षौ चीरकृष्णाजिनाम्बरौ ॥ १७॥\"],\"en\":[\"tarunau rupasampannau sukumarau mahabalau.\",\"pundarikavisalaksau cirakrsnajinambarau. 17.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"ફલમૂલાશિનૌ દાન્તૌ તાપસૌ બ્રહ્મચારિણૌ ।\",\"પુત્રૌ દશરથસ્યૈતૌ ભ્રાતરૌ રામલક્ષ્મણૌ ॥ ૧૮॥\"],\"hi\":[\"फलमूलाशिनौ दान्तौ तापसौ ब्रह्मचारिणौ ।\",\"पुत्रौ दशरथस्यैतौ भ्रातरौ रामलक्ष्मणौ ॥ १८॥\"],\"en\":[\"phalamulasinau dantau tapasau brahmacarinau.\",\"putrau dasarathasyaitau bhratarau ramalaksmanau. 18.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"શરણ્યૌ સર્વસત્ત્વાનાં શ્રેષ્ઠૌ સર્વધનુષ્મતામ્ ।\",\"રક્ષઃ કુલનિહન્તારૌ ત્રાયેતાં નો રઘૂત્તમૌ ॥ ૧૯॥\"],\"hi\":[\"शरण्यौ सर्वसत्त्वानां श्रेष्ठौ सर्वधनुष्मताम् ।\",\"रक्षः कुलनिहन्तारौ त्रायेतां नो रघूत्तमौ ॥ १९॥\"],\"en\":[\"saranyau sarvasattvanam sresthau sarvadhanusmatam.\",\"raksah kulanihantarau trayetam no raghuttamau. 1 9.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"આત્તસજ્જધનુષાવિષુસ્પૃશાવક્ષયાશુગનિષઙ્ગસઙ્ગિનૌ ।\",\"રક્ષણાય મમ રામલક્ષ્મણાવગ્રતઃ પથિ સદૈવ ગચ્છતામ્ ॥ ૨૦॥\"],\"hi\":[\"आत्तसज्जधनुषाविषुस्पृशावक्षयाशुगनिषङ्गसङ्गिनौ ।\",\"रक्षणाय मम रामलक्ष्मणावग्रतः पथि सदैव गच्छताम् ॥ २०॥\"],\"en\":[\"attasajjadhanusavisusprsavaksayasuganisangasanginau.\",\"raksanaya mama ramalaksmanavagratah pathi sadaiva gacchatam. 20.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"સન્નદ્ધઃ કવચી ખડ્ગી ચાપબાણધરો યુવા ।\",\"ગચ્છન્મનોરથોસ્માકં રામઃ પાતુ સલક્ષ્મણઃ ॥ ૨૧॥\"],\"hi\":[\"सन्नद्धः कवची खड्गी चापबाणधरो युवा ।\",\"गच्छन्मनोरथोस्माकं रामः पातु सलक्ष्मणः ॥ २१॥\"],\"en\":[\"sannad\'dhah kavaci khadgi capabanadharo yuva.\",\"gacchanmanorathosmakam ramah patu salaksmanah. 21.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"રામો દાશરથિઃ શૂરો લક્ષ્મણાનુચરો બલી ।\",\"કાકુત્સ્થઃ પુરુષઃ પૂર્ણઃ કૌસલ્યેયો રઘુત્તમઃ ॥ ૨૨॥\"],\"hi\":[\"रामो दाशरथिः शूरो लक्ष्मणानुचरो बली ।\",\"काकुत्स्थः पुरुषः पूर्णः कौसल्येयो रघुत्तमः ॥ २२॥\"],\"en\":[\"ramo dasarathih suro laksmananucaro bali.\",\"kakutsthah purusah purnah kausalyeyo raghuttamah. 22.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"વેદાન્તવેદ્યો યજ્ઞેશઃ પુરાણપુરુષોત્તમઃ ।\",\"જાનકીવલ્લભઃ શ્રીમાન્ અપ્રમેય પરાક્રમઃ ॥ ૨૩॥\"],\"hi\":[\"वेदान्तवेद्यो यज्ञेशः पुराणपुरुषोत्तमः ।\",\"जानकीवल्लभः श्रीमान् अप्रमेय पराक्रमः ॥ २३॥\"],\"en\":[\"vedantavedyo yajnesah puranapurusottamah.\",\"janakivallabhah sriman aprameya parakramah. 23.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"ઇત્યેતાનિ જપન્નિત્યં મદ્ભક્તઃ શ્રદ્ધયાન્વિતઃ ।\",\"અશ્વમેધાધિકં પુણ્યં સમ્પ્રાપ્નોતિ ન સંશયઃ ॥ ૨૪॥\"],\"hi\":[\"इत्येतानि जपन्नित्यं मद्भक्तः श्रद्धयान्वितः ।\",\"अश्वमेधाधिकं पुण्यं सम्प्राप्नोति न संशयः ॥ २४॥\"],\"en\":[\"ityetani japannityam madbhaktah srad\'dhayanvitah.\",\"asvamedhadhikam punyam samprapnoti na sansayah. 24.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"રામં દુર્વાદલશ્યામં પદ્માક્ષં પીતવાસસમ્ ।\",\"સ્તુવન્તિ નામભિર્દિવ્યૈઃ ન તે સંસારિણો નરઃ ॥ ૨૫॥\"],\"hi\":[\"रामं दुर्वादलश्यामं पद्माक्षं पीतवाससम् ।\",\"स्तुवन्ति नामभिर्दिव्यैः न ते संसारिणो नरः ॥ २५॥\"],\"en\":[\"ramam durvadalasyamam padmaksam pitavasasam.\",\"stuvanti namabhirdivyaih na te sansarino narah. 25.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"રામં લક્ષ્મણપૂર્વજં રઘુવરં સીતાપતિં સુન્દરમ્ ।\",\"કાકુત્સ્થં કરુણાર્ણવં ગુણનિધિં વિપ્રપ્રિયં ધાર્મિકમ્ ।\",\"રાજેન્દ્રં સત્યસન્ધં દશરથતનયં શ્યામલં શાન્તમૂર્તિમ્ ।\",\"વન્દે લોકાભિરામં રઘુકુલતિલકં રાઘવં રાવણારિમ્ ॥ ૨૬॥\"],\"hi\":[\"रामं लक्ष्मणपूर्वजं रघुवरं सीतापतिं सुन्दरम् ।\",\"काकुत्स्थं करुणार्णवं गुणनिधिं विप्रप्रियं धार्मिकम् ।\",\"राजेन्द्रं सत्यसन्धं दशरथतनयं श्यामलं शान्तमूर्तिम् ।\",\"वन्दे लोकाभिरामं रघुकुलतिलकं राघवं रावणारिम् ॥ २६॥\"],\"en\":[\"ramam laksmanapurvajam raghuvaram sitapatim sundaram.\",\"kakutstham karunarnavam gunanidhim viprapriyam dharmikam.\",\"rajendram satyasandham dasarathatanayam syamalam santamurtim.\",\"vande lokabhiramam raghukulatilakam raghavam ravanarim. 26.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"રામાય રામભદ્રાય રામચન્દ્રાય વેધસે ।\",\"રઘુનાથાય નાથાય સીતાયાઃ પતયે નમઃ ॥ ૨૭॥\"],\"hi\":[\"रामाय रामभद्राय रामचन्द्राय वेधसे ।\",\"रघुनाथाय नाथाय सीतायाः पतये नमः ॥ २७॥\"],\"en\":[\"ramaya ramabhadraya ramacandraya vedhase.\",\"raghunathaya nathaya sitayah pataye namah. 27.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"શ્રીરામ રામ રઘુનન્દન રામ રામ ।\",\"શ્રીરામ રામ ભરતાગ્રજ રામ રામ ।\",\"શ્રીરામ રામ રણકર્કશ રામ રામ ।\",\"શ્રીરામ રામ શરણં ભવ રામ રામ ॥ ૨૮॥\"],\"hi\":[\"श्रीराम राम रघुनन्दन राम राम ।\",\"श्रीराम राम भरताग्रज राम राम ।\",\"श्रीराम राम रणकर्कश राम राम ।\",\"श्रीराम राम शरणं भव राम राम ॥ २८॥\"],\"en\":[\"srirama rama raghunandana rama rama.\",\"srirama rama bharatagraja rama rama.\",\"srirama rama ranakarkasa rama rama.\",\"srirama rama saranam bhava rama rama. 28.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"શ્રીરામચન્દ્રચરણૌ મનસા સ્મરામિ ।\",\"શ્રીરામચન્દ્રચરણૌ વચસા ગૃણામિ ।\",\"શ્રીરામચન્દ્રચરણૌ શિરસા નમામિ ।\",\"શ્રીરામચન્દ્રચરણૌ શરણં પ્રપદ્યે ॥ ૨૯॥\"],\"hi\":[\"श्रीरामचन्द्रचरणौ मनसा स्मरामि ।\",\"श्रीरामचन्द्रचरणौ वचसा गृणामि ।\",\"श्रीरामचन्द्रचरणौ शिरसा नमामि ।\",\"श्रीरामचन्द्रचरणौ शरणं प्रपद्ये ॥ २९॥\"],\"en\":[\"sriramacandracaranau manasa smarami.\",\"sriramacandracaranau vacasa grnami.\",\"sriramacandracaranau sirasa namami.\",\"sriramacandracaranau saranam prapadye. 2 9.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"માતા રામો મત્પિતા રામચન્દ્રઃ ।\",\"સ્વામી રામો મત્સખા રામચન્દ્રઃ ।\",\"સર્વસ્વં મે રામચન્દ્રો દયાલુઃ ।\",\"નાન્યં જાને નૈવ જાને ન જાને ॥ ૩૦॥\"],\"hi\":[\"माता रामो मत्पिता रामचन्द्रः ।\",\"स्वामी रामो मत्सखा रामचन्द्रः ।\",\"सर्वस्वं मे रामचन्द्रो दयालुः ।\",\"नान्यं जाने नैव जाने न जाने ॥ ३०॥\"],\"en\":[\"mata ramo matpita ramacandrah.\",\"svami ramo matsakha ramacandrah.\",\"sarvasvam me ramacandro dayaluh.\",\"nan\'yam jane naiva jane na jane. 30.\"]}},{\"type\":\"verse\",\"lines\":{\"gu\":[\"દક્ષિણે લક્ષ્મણો યસ્ય વામે તુ જનકાત્મજા ।\",\"પુરતો માર